@startuml

class City {}

class H2SLocation {
  + Name : string
}

H2SLocation "*" -- "1" City

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
}

class PickupRequest {
  + Description : string
  + RequestedWeekday : string
  + PickupTime : time
}

Resident "1" -- "*" PickupRequest

class Item {
  + Dimensions : string
  + Weight : float
}

PickupRequest "1" -- "*" Item

class Vehicle {
  + StorageSpace : float
}

class VolunteerDriver {
  + AvailableDays : string[]
}

class PickupRoute {
  + Date : date
}

Vehicle "1" -- "*" PickupRoute
VolunteerDriver "*" -- "*" PickupRoute
PickupRoute "1" -- "*" PickupRequest

class DistributionCenter {
}

H2SLocation "1" *-- "1" DistributionCenter

class SecondHandArticle {
  + RFID : string
  + Category : string
  + Description : string
}

class NonPerishableFood {
}

Item "1" -- "1" SecondHandArticle
Item "1" -- "0..1" NonPerishableFood

class Employee {
}

Employee "*" -- "1" DistributionCenter

class Client {
  + HomeAddress : string
  + NeededCategories : string[]
}

Employee "1" -- "*" Client : calls
Employee "1" -- "*" SecondHandArticle : examines
Employee "1" -- "*" SecondHandArticle : assignsCategory

SecondHandArticle "*" -- "1" DistributionCenter

class FoodBank {
}

NonPerishableFood "*" -- "1" FoodBank

@enduml

